<?php if(($installment_edit_panel??null)!==null&&($can_issue??false)&&($can_configure??false)){ $edit=$installment_edit_panel; ?>
<div class="panel panel-default"><div class="panel-body"><h4>Editar parcelas de <?= $e($edit['group_id']); ?></h4>
<p>Revise valores e vencimentos das parcelas ainda pendentes. O total do grupo e a fatura emitida são preservados. A atualização pode gerar notificações do Asaas. Cada parcela tem confirmação própria; resultados incertos são consultados sem repetir o envio.</p>
<?php if(($installment_edit_result??null)!==null){ ?><p role="status"><?= $installment_edit_result['complete']?'Alterações confirmadas para todas as parcelas selecionadas.':'Operação parcial: confira e retome a mesma revisão.'; ?></p><?php } ?>
<?php if($edit['pending']!==null){ ?><p>Há uma revisão em andamento. A conciliação e outras alterações deste grupo permanecem bloqueadas até a confirmação.</p><form method="post" action="<?= $e($action_url); ?>#monitor"><?php $hidden(['action'=>'resume_installment_edit','group_origin'=>$edit['group_origin'],'review_hash'=>$edit['pending']['key'],'company_asaas_preferences_csrf'=>$preferences_csrf]); ?><label><input type="checkbox" name="confirm" value="1"> Confirmo retomar somente a seleção já aprovada</label><button type="submit" class="btn btn-default">Consultar e retomar</button></form>
<?php }else{ $proposal=$installment_edit_review??null; ?><form method="post" action="<?= $e($action_url); ?>#monitor"><?php $hidden(['action'=>$proposal?'execute_installment_edit':'review_installment_edit','group_origin'=>$edit['group_origin'],'company_asaas_preferences_csrf'=>$preferences_csrf]); if($proposal)$hidden(['review_hash'=>$proposal['key']]); ?>
<div class="table-responsive"><table class="table"><thead><tr><th>Parcela</th><th>Cobrança</th><th>Valor</th><th>Vencimento</th></tr></thead><tbody><?php foreach($edit['members'] as $member){ $target=$proposal['after'][$member['id']]??$member; ?><tr><td><?= (int)$member['number']; ?></td><td><?= $e($member['id']); ?></td><td><input class="form-control" name="changes[<?= $e($member['id']); ?>][value]" value="<?= $e($target['value']); ?>" inputmode="decimal" required <?= $proposal?'readonly':''; ?>></td><td><input class="form-control" type="date" name="changes[<?= $e($member['id']); ?>][due_date]" value="<?= $e($target['due_date']); ?>" required <?= $proposal?'readonly':''; ?>></td></tr><?php } ?></tbody></table></div>
<?php if($proposal){ ?><label><input type="checkbox" name="confirm" value="1"> Confirmo atualizar as parcelas revisadas no Asaas</label><?php } ?><button class="btn btn-primary" type="submit"><?= $proposal?'Confirmar alterações':'Revisar alterações'; ?></button></form><?php } ?></div></div><?php } ?>
